import random
from datetime import date

# 1. 日付を出力する関数
def get_today():
    return date.today()

# 2. 数字を入力してもらう関数
def get_start():
    i = input("시작을 입력해주세요. :")
    return i

# 3. ランダムな数を作る関数
def get_random():
    return random.randint(1, 6)

# 4. 動物の名前を対応させる関数
def get_animal(n, animal_list):
    # リストの最初は0なので -1 する
    return animal_list[n-1]

