from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from pydantic import BaseModel

app = FastAPI()

# 1. 로그인 데이터 모델 정의
class LoginRequest(BaseModel):
    username: str
    password: str

# 2. 로그인 화면 (HTML + JavaScript)
# 파이썬 코드 안에 HTML을 직접 작성합니다.
html_content = """
<!DOCTYPE html>
<html>
    <head>
        <title>FastAPI 로그인 하기</title>
        <style>
            body { font-family: sans-serif; display: flex; justify-content: center; padding-top: 50px; }
            .login-box { border: 1px solid #ccc; padding: 20px; border-radius: 8px; box-shadow: 2px 2px 10px #eee; }
            input { display: block; margin-bottom: 10px; width: 200px; padding: 8px; }
            button { width: 100%; padding: 10px; background-color: #00c4b4; color: white; border: none; cursor: pointer; }
        </style>
    </head>
    <body>
        <div class="login-box">
            <h2>로그인 미션</h2>
            <input type="text" id="username" placeholder="아이디">
            <input type="password" id="password" placeholder="비밀번호">
            <button onclick="sendLogin()">로그인하기</button>
            <p id="result-message" style="margin-top: 15px; font-weight: bold;"></p>
        </div>

        <script>
            async function sendLogin() {
                const userVal = document.getElementById('username').value;
                const passVal = document.getElementById('password').value;
                const resMsg = document.getElementById('result-message');

                // FastAPI의 /login 엔드포인트로 데이터 전송
                const response = await fetch('/login', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ username: userVal, password: passVal })
                });

                const data = await response.json();

                // 서버에서 받은 응답(JSON)을 화면에 표시
                resMsg.innerText = data.message;
                resMsg.style.color = data.success ? "blue" : "red";
            }
        </script>
    </body>
</html>
"""

# [엔드포인트 1] 접속 시 로그인 화면을 보여줌
@app.get("/", response_class=HTMLResponse)
def get_home():
    return html_content

# [엔드포인트 2] 로그인 기능을 수행 (이미지 미션 조건 반영)
@app.post("/login")
def login_check(user: LoginRequest):

    if user.username == "test" and user.password == "test1234":
        return {"success": True, "message": "로그인 성공!"}
    else:
        return {"success": False, "message": "로그인 실패"}

